window.__PAGES=window.__PAGES||{};window.__PAGES["pages/ticketing.html"]="<!-- Ticketing Page — ticket list, filters, CRUD -->\n<style>\n.tkt-toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap}\n.tkt-toolbar input{flex:1;min-width:200px;padding:7px 12px;border:1px solid var(--border);border-radius:20px;font-size:13px;background:var(--card)}\n.tkt-toolbar input:focus{outline:2px solid var(--accent);outline-offset:-1px}\n.tkt-priority-chip{padding:5px 12px;border-radius:16px;border:1px solid var(--border);font-size:12px;cursor:pointer;background:var(--card)}\n.tkt-priority-chip.active{background:var(--accent);color:#fff;border-color:var(--accent)}\n.data-table .tkt-row{cursor:pointer;transition:.1s}\n.data-table .tkt-row:hover{background:rgba(79,70,229,.04)}\n.data-table .tkt-row.expanded{background:rgba(79,70,229,.06)}\n.tkt-detail td{padding:0 12px 12px;background:rgba(79,70,229,.03)}\n.tkt-detail-inner{display:flex;gap:24px;padding:12px 0;font-size:13px}\n.tkt-detail-inner .dk{font-size:11px;color:var(--muted);margin-bottom:2px}\n.tkt-detail-inner .dv{font-weight:600}\n.tkt-detail-actions{display:flex;gap:6px;margin-left:auto;align-items:flex-start}\n.priority-badge{display:inline-block;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:600}\n.priority-badge.high{background:#fef2f2;color:#dc2626}.priority-badge.medium{background:#fef3c7;color:#b45309}.priority-badge.low{background:#f0fdf4;color:#15803d}\n.stat-row{display:flex;gap:12px;padding:0 24px 12px}\n.tkt-count{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:12px 18px;text-align:center;flex:1}\n.tkt-count .val{font-size:22px;font-weight:700}.tkt-count .lbl{font-size:11px;color:var(--muted)}\n</style>\n\n<div class=\"page-header\">\n  <h1>🎫 Tiket</h1>\n  <button class=\"btn primary\" onclick=\"openCreateTkt()\">+ Tiket Baru</button>\n</div>\n\n<div class=\"stat-row\" id=\"tktStats\"></div>\n\n<div class=\"page-filters\">\n  <div id=\"statusChips\">\n    <span class=\"filter-chip active\" onclick=\"setTktStatusFilter(this,'all')\">Semua</span>\n    <span class=\"filter-chip\" onclick=\"setTktStatusFilter(this,'open')\">🔵 Open</span>\n    <span class=\"filter-chip\" onclick=\"setTktStatusFilter(this,'pending')\">🟡 Pending</span>\n    <span class=\"filter-chip\" onclick=\"setTktStatusFilter(this,'resolved')\">🟢 Resolved</span>\n    <span class=\"filter-chip\" onclick=\"setTktStatusFilter(this,'closed')\">⚪ Closed</span>\n  </div>\n  <select id=\"tktPriorityFilter\" onchange=\"renderTktTable()\" style=\"padding:5px 10px;border:1px solid var(--border);border-radius:16px;font-size:12px;background:var(--card);cursor:pointer\">\n    <option value=\"all\">Semua Prioritas</option>\n    <option value=\"high\">🔴 Tinggi</option>\n    <option value=\"medium\">🟡 Sedang</option>\n    <option value=\"low\">🟢 Rendah</option>\n  </select>\n  <div class=\"tkt-toolbar\" style=\"margin-left:auto;flex:1;max-width:320px\">\n    <input type=\"text\" id=\"tktSearch\" placeholder=\"Cari tiket…\" oninput=\"renderTktTable()\">\n  </div>\n</div>\n\n<div class=\"page-body\">\n  <table class=\"data-table\">\n    <thead>\n      <tr><th>ID</th><th>Subjek</th><th>Kontak</th><th>Status</th><th>Prioritas</th><th>Agen</th><th>Dibuat</th></tr>\n    </thead>\n    <tbody id=\"tktBody\"></tbody>\n  </table>\n  <div id=\"tktEmpty\" style=\"display:none;text-align:center;padding:40px;color:var(--muted)\">\n    <div style=\"font-size:36px;opacity:.4;margin-bottom:8px\">🎫</div>\n    Tidak ada tiket ditemukan\n  </div>\n</div>\n\n<!-- Create/Edit Modal -->\n<div class=\"modal-overlay\" id=\"tktModal\">\n  <div class=\"modal\">\n    <h3 id=\"tktModalTitle\">Buat Tiket Baru</h3>\n    <label>Subjek<input type=\"text\" id=\"tktSubject\" placeholder=\"Ringkasan masalah\"></label>\n    <label>Kontak<select id=\"tktContact\"><option value=\"\">— Pilih Kontak —</option></select></label>\n    <label>Prioritas<select id=\"tktPriority\"><option value=\"medium\">Sedang</option><option value=\"high\">Tinggi</option><option value=\"low\">Rendah</option></select></label>\n    <label>Agen<select id=\"tktAssignee\"><option value=\"\">— Tidak Ditugaskan —</option></select></label>\n    <div class=\"modal-actions\">\n      <button class=\"btn\" onclick=\"closeTktModal()\">Batal</button>\n      <button class=\"btn primary\" onclick=\"saveTkt()\">Simpan</button>\n    </div>\n  </div>\n</div>\n\n<!-- Delete Confirm -->\n<div class=\"modal-overlay\" id=\"tktDelModal\">\n  <div class=\"modal\">\n    <h3>Hapus Tiket</h3>\n    <p style=\"font-size:13px;color:var(--muted);margin-bottom:4px\">Apakah Anda yakin ingin menghapus tiket ini? Tindakan ini tidak dapat dibatalkan.</p>\n    <div class=\"modal-actions\">\n      <button class=\"btn\" onclick=\"document.getElementById('tktDelModal').classList.remove('open')\">Batal</button>\n      <button class=\"btn danger\" onclick=\"confirmDelTkt()\">Hapus</button>\n    </div>\n  </div>\n</div>\n\n<script>\nlet tktStatusFilter='all', tktExpandedId=null, tktEditId=null, tktDelId=null;\n\nfunction setTktStatusFilter(el,status){\n  tktStatusFilter=status;\n  document.querySelectorAll('#statusChips .filter-chip').forEach(c=>c.classList.remove('active'));\n  el.classList.add('active');\n  renderTktTable();\n}\n\nfunction renderTktStats(){\n  const tkts=DB.tickets||[];\n  const open=tkts.filter(t=>t.status==='open').length;\n  const pending=tkts.filter(t=>t.status==='pending').length;\n  const resolved=tkts.filter(t=>t.status==='resolved').length;\n  const closed=tkts.filter(t=>t.status==='closed').length;\n  document.getElementById('tktStats').innerHTML=`\n    <div class=\"tkt-count\"><div class=\"val\">${tkts.length}</div><div class=\"lbl\">Total</div></div>\n    <div class=\"tkt-count\"><div class=\"val\" style=\"color:#2563eb\">${open}</div><div class=\"lbl\">Open</div></div>\n    <div class=\"tkt-count\"><div class=\"val\" style=\"color:#b45309\">${pending}</div><div class=\"lbl\">Pending</div></div>\n    <div class=\"tkt-count\"><div class=\"val\" style=\"color:#15803d\">${resolved}</div><div class=\"lbl\">Resolved</div></div>\n    <div class=\"tkt-count\"><div class=\"val\" style=\"color:#6b7280\">${closed}</div><div class=\"lbl\">Closed</div></div>`;\n}\n\nfunction renderTktTable(){\n  const q=(document.getElementById('tktSearch')?.value||'').toLowerCase();\n  const pf=document.getElementById('tktPriorityFilter').value;\n  let tkts=(DB.tickets||[]).filter(t=>{\n    if(tktStatusFilter!=='all'&&t.status!==tktStatusFilter)return false;\n    if(pf!=='all'&&t.priority!==pf)return false;\n    if(q){\n      const ct=DB.contacts.find(c=>c.id===t.contactId);\n      const haystack=(t.subject+' '+(ct?.name||'')+' '+t.id).toLowerCase();\n      if(!haystack.includes(q))return false;\n    }\n    return true;\n  });\n  tkts.sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));\n  const body=document.getElementById('tktBody');\n  const empty=document.getElementById('tktEmpty');\n  if(!tkts.length){body.innerHTML='';empty.style.display='';renderTktStats();return}\n  empty.style.display='none';\n  body.innerHTML=tkts.map(t=>{\n    const ct=DB.contacts.find(c=>c.id===t.contactId);\n    const ag=DB.agents.find(a=>a.id===t.assignee);\n    const expanded=t.id===tktExpandedId;\n    const statusCls=t.status;\n    const priCls=t.priority;\n    const priLabel={high:'Tinggi',medium:'Sedang',low:'Rendah'}[t.priority]||t.priority;\n    const row=`<tr class=\"tkt-row${expanded?' expanded':''}\" onclick=\"toggleTktDetail('${t.id}')\">\n      <td><code style=\"font-size:11px;color:var(--muted)\">${t.id.slice(0,8)}</code></td>\n      <td style=\"font-weight:600\">${t.subject}</td>\n      <td>${ct?ct.name:'-'}</td>\n      <td><span class=\"status ${statusCls}\">${t.status}</span></td>\n      <td><span class=\"priority-badge ${priCls}\">${priLabel}</span></td>\n      <td>${ag?ag.name:'-'}</td>\n      <td style=\"font-size:12px;color:var(--muted)\">${fmtDate(t.createdAt)}</td>\n    </tr>`;\n    if(!expanded)return row;\n    const detail=`<tr class=\"tkt-detail\"><td colspan=\"7\">\n      <div class=\"tkt-detail-inner\">\n        <div><div class=\"dk\">ID Tiket</div><div class=\"dv\">${t.id}</div></div>\n        <div><div class=\"dk\">Kontak</div><div class=\"dv\">${ct?ct.name:'-'} ${ct?'('+ct.phone+')':''}</div></div>\n        <div><div class=\"dk\">Agen</div><div class=\"dv\">${ag?ag.name:'Belum ditugaskan'}</div></div>\n        <div><div class=\"dk\">Dibuat</div><div class=\"dv\">${fmtDate(t.createdAt)} ${fmtTime(t.createdAt)}</div></div>\n        <div class=\"tkt-detail-actions\">\n          <select class=\"btn\" style=\"font-size:12px\" onchange=\"changeTktStatus('${t.id}',this.value)\" onclick=\"event.stopPropagation()\">\n            ${['open','pending','resolved','closed'].map(s=>`<option value=\"${s}\"${t.status===s?' selected':''}>${s}</option>`).join('')}\n          </select>\n          <button class=\"btn\" onclick=\"event.stopPropagation();openEditTkt('${t.id}')\" style=\"font-size:12px\">✏️ Edit</button>\n          <button class=\"btn danger\" onclick=\"event.stopPropagation();openDelTkt('${t.id}')\" style=\"font-size:12px\">🗑️ Hapus</button>\n        </div>\n      </div>\n    </td></tr>`;\n    return row+detail;\n  }).join('');\n  renderTktStats();\n}\n\nfunction toggleTktDetail(id){\n  tktExpandedId=tktExpandedId===id?null:id;\n  renderTktTable();\n}\n\nfunction changeTktStatus(id,status){\n  dbUpdate('tickets',id,{status});\n  showToast('Status tiket diperbarui');\n  renderTktTable();\n}\n\nfunction populateModalDropdowns(){\n  const ctSel=document.getElementById('tktContact');\n  ctSel.innerHTML='<option value=\"\">— Pilih Kontak —</option>'+(DB.contacts||[]).map(c=>`<option value=\"${c.id}\">${c.name} (${c.phone})</option>`).join('');\n  const agSel=document.getElementById('tktAssignee');\n  agSel.innerHTML='<option value=\"\">— Tidak Ditugaskan —</option>'+(DB.agents||[]).map(a=>`<option value=\"${a.id}\">${a.name}</option>`).join('');\n}\n\nfunction openCreateTkt(){\n  tktEditId=null;\n  document.getElementById('tktModalTitle').textContent='Buat Tiket Baru';\n  document.getElementById('tktSubject').value='';\n  document.getElementById('tktPriority').value='medium';\n  populateModalDropdowns();\n  document.getElementById('tktContact').value='';\n  document.getElementById('tktAssignee').value='';\n  document.getElementById('tktModal').classList.add('open');\n}\n\nfunction openEditTkt(id){\n  const t=dbFind('tickets',id);if(!t)return;\n  tktEditId=id;\n  document.getElementById('tktModalTitle').textContent='Edit Tiket';\n  populateModalDropdowns();\n  document.getElementById('tktSubject').value=t.subject;\n  document.getElementById('tktContact').value=t.contactId||'';\n  document.getElementById('tktPriority').value=t.priority;\n  document.getElementById('tktAssignee').value=t.assignee||'';\n  document.getElementById('tktModal').classList.add('open');\n}\n\nfunction closeTktModal(){\n  document.getElementById('tktModal').classList.remove('open');\n}\n\nfunction saveTkt(){\n  const subject=document.getElementById('tktSubject').value.trim();\n  if(!subject){showToast('Subjek wajib diisi');return}\n  const data={\n    subject,\n    contactId:document.getElementById('tktContact').value,\n    priority:document.getElementById('tktPriority').value,\n    assignee:document.getElementById('tktAssignee').value\n  };\n  if(tktEditId){\n    dbUpdate('tickets',tktEditId,data);\n    showToast('Tiket diperbarui');\n  } else {\n    dbAdd('tickets',{id:genId('tkt'),...data,status:'open',teamId:'',conversationId:'',createdAt:new Date().toISOString()});\n    showToast('Tiket dibuat');\n  }\n  closeTktModal();\n  renderTktTable();\n}\n\nfunction openDelTkt(id){tktDelId=id;document.getElementById('tktDelModal').classList.add('open')}\nfunction confirmDelTkt(){\n  if(tktDelId){dbRemove('tickets',tktDelId);showToast('Tiket dihapus');tktDelId=null}\n  document.getElementById('tktDelModal').classList.remove('open');\n  tktExpandedId=null;\n  renderTktTable();\n}\n\n// Init\nrenderTktTable();\n</script>\n";
